#!/bin/bash
set -e
export LANG=C.UTF-8
VIVADO=/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado
mkdir -p /opt/lzh/step03/dsptest
cd /opt/lzh/step03/dsptest

echo '' | base64 -d > top_dsp_REF.v
echo '' | base64 -d > top_dsp_VAR.v
echo '' | base64 -d > stage_dsp_ref.tcl
echo '' | base64 -d > stage_dsp_var.tcl
echo '' | base64 -d > diff_dsp.py
echo "=== Synth ref ==="
$VIVADO -mode batch -source stage_dsp_ref.tcl 2>&1 | tail -8

echo "=== Synth var ==="
$VIVADO -mode batch -source stage_dsp_var.tcl 2>&1 | tail -8

echo "=== Files ==="
ls -la *.bit

echo "=== Diff ==="
python3 diff_dsp.py ref.bit var_cead0.bit
